#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePinkhaApi: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = PinkhaApi

    public static func lift(_ handle: UInt64) throws -> PinkhaApi {
        return PinkhaApi(unsafeFromHandle: handle)
    }

    public static func lower(_ value: PinkhaApi) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PinkhaApi {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: PinkhaApi, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypePinkhaApi_lift(_ handle: UInt64) throws -> PinkhaApi {
    return try FfiConverterTypePinkhaApi.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypePinkhaApi_lower(_ value: PinkhaApi) -> UInt64 {
    return FfiConverterTypePinkhaApi.lower(value)
}




/**
 * One hit from a block-content search — the leaf metadata plus a
 * snippet of the matching block for a Notion-style preview.
 */
public struct BlockSearchHitFfi: Equatable, Hashable {
    public var doc: LeafMetaFfi
    public var blockId: String
    public var snippet: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(doc: LeafMetaFfi, blockId: String, snippet: String) {
        self.doc = doc
        self.blockId = blockId
        self.snippet = snippet
    }

    

    
}

#if compiler(>=6)
extension BlockSearchHitFfi: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBlockSearchHitFfi: FfiConverterRustBuffer {
    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BlockSearchHitFfi {
        return
            try BlockSearchHitFfi(
                doc: FfiConverterTypeLeafMetaFfi.read(from: &buf), 
                blockId: FfiConverterString.read(from: &buf), 
                snippet: FfiConverterString.read(from: &buf)
        )
    }

    public static func write(_ value: BlockSearchHitFfi, into buf: inout [UInt8]) {
        FfiConverterTypeLeafMetaFfi.write(value.doc, into: &buf)
        FfiConverterString.write(value.blockId, into: &buf)
        FfiConverterString.write(value.snippet, into: &buf)
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeBlockSearchHitFfi_lift(_ buf: RustBuffer) throws -> BlockSearchHitFfi {
    return try FfiConverterTypeBlockSearchHitFfi.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeBlockSearchHitFfi_lower(_ value: BlockSearchHitFfi) -> RustBuffer {
    return FfiConverterTypeBlockSearchHitFfi.lower(value)
}


