public 
enum PinkhaError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case NotFound(id: String
    )
    case InvalidOperation(detail: String
    )
    case Storage(detail: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension PinkhaError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePinkhaError: FfiConverterRustBuffer {
    typealias SwiftType = PinkhaError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PinkhaError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotFound(
            id: try FfiConverterString.read(from: &buf)
            )
        case 2: return .InvalidOperation(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Storage(
            detail: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: PinkhaError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .NotFound(id):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .InvalidOperation(detail):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Storage(detail):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(detail, into: &buf)
            
        }
    }
}


